_CORE_SRC = '# Action: [(from_node, to_node, unit_type, count), ...]\n# Payout: equal capacities split demand, each serving min(capacity, demand / 2).\n# Otherwise the larger capacity serves min(capacity_big, demand) first, and the\n# smaller serves min(capacity_small, demand - served_big).\n# Upkeep: every heavy away from its own base costs 3.0 per turn; every light\n# away from its own base costs 1.0. Moves precede payout, one edge per unit.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 70\n\n\ndef payout(ours, theirs, demand):\n    if ours == theirs:\n        served = min(ours, demand / 2.0)\n        return served, served\n    if ours > theirs:\n        first = min(ours, demand)\n        return first, min(theirs, demand - first)\n    first = min(theirs, demand)\n    return min(ours, demand - first), first\n\n\ndef preprocess_map(n, edges):\n    adj = [[] for _ in range(n)]\n    for a, b in edges:\n        adj[a].append(b)\n        adj[b].append(a)\n    for row in adj:\n        row.sort()\n    dist = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adj[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        dist.append(row)\n    hops = [[i] * n for i in range(n)]\n    for s in range(n):\n        for t in range(n):\n            if s != t:\n                hops[s][t] = min(\n                    v for v in adj[s] if dist[v][t] == dist[s][t] - 1\n                )\n    return adj, dist, hops\n\n\ndef legal_action(units, targets, hops, adj, heavy, light):\n    available = {"heavy": list(heavy), "light": list(light)}\n    grouped = {}\n    for (kind, source), target in zip(units, targets):\n        if source != target:\n            dest = hops[source][target]\n            key = (source, dest, kind)\n            grouped[key] = grouped.get(key, 0) + 1\n    result = []\n    for (source, dest, kind), count in sorted(grouped.items()):\n        if dest not in adj[source]:\n            continue\n        count = min(count, available[kind][source])\n        if count > 0:\n            result.append((int(source), int(dest), kind, int(count)))\n            available[kind][source] -= count\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.base_estimates = []\n        self.last_seen = []\n        self.last_surge = []\n        self.previous_enemy = None\n        self.mobility = 0.5\n        self.saved_targets = []\n        self.previous_turn = -2\n        self.bad_reports = 0\n\n    def _demand_forecast(self, obs, horizon):\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        demand = obs.get("demand", [None] * n)\n        surges = obs.get("surge_turns_left", [None] * n)\n        for v in range(n):\n            if demand[v] is not None:\n                counter = surges[v] or 0\n                self.base_estimates[v] = float(demand[v]) / (3 if counter else 1)\n                self.last_seen[v] = turn\n                self.last_surge[v] = counter\n        probabilities = []\n        for k in range(horizon):\n            row = []\n            for v in range(n):\n                age = turn + k - self.last_seen[v]\n                if self.last_seen[v] < 0:\n                    p = 1.0 - 0.9 ** 3\n                elif age < self.last_surge[v]:\n                    p = 1.0\n                else:\n                    p = 1.0 - 0.9 ** min(3, max(0, age))\n                row.append(p)\n            probabilities.append(row)\n        return probabilities\n\n    def _predict_enemy(self, obs, probabilities, deadline):\n        n = obs["n_nodes"]\n        eh = obs["opponent_heavy"]\n        el = obs["opponent_light"]\n        initial = [8 * eh[v] + 3 * el[v] for v in range(n)]\n        if self.previous_enemy is not None:\n            changed = sum(abs(initial[v] - self.previous_enemy[v]) for v in range(n))\n            activity = min(1.0, changed / 45.0)\n            self.mobility = 0.75 * self.mobility + 0.25 * activity\n        self.previous_enemy = initial[:]\n        predicted = initial[:]\n        enemy_base = obs["opponent_base"]\n        # Coordinate best response using only one-edge-reachable destinations.\n        # Keeping the stay scenario separately avoids trusting this model too much.\n        for kind, counts, capacity, upkeep in (\n            ("light", el, 3, 1.0), ("heavy", eh, 8, 3.0)\n        ):\n            for source in range(n):\n                for _ in range(counts[source]):\n                    if time.perf_counter() >= deadline:\n                        return initial, predicted\n                    predicted[source] -= capacity\n                    best = source\n                    best_value = -1e100\n                    for dest in [source] + self.adj[source]:\n                        d = self.base_estimates[dest]\n                        p = probabilities[0][dest]\n                        before = predicted[dest]\n                        # Expected private revenue; not a margin-maximising oracle.\n                        value = ((1 - p) * (min(before + capacity, d) - min(before, d))\n                                 + p * (min(before + capacity, 3 * d) - min(before, 3 * d))\n                                 - (upkeep if dest != enemy_base else 0.0))\n                        if dest != source:\n                            value -= 0.12\n                        if value > best_value + 1e-9:\n                            best_value, best = value, dest\n                    predicted[best] += capacity\n        return initial, predicted\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0001, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs["edges"])\n            self.adj, self.dist, self.hops = self.map_data\n            self.base_estimates = [3.8] * n\n            self.last_seen = [-1000] * n\n            self.last_surge = [0] * n\n        home = int(obs["player_base"])\n        enemy_home = int(obs["opponent_base"])\n        self.base_estimates[home] = self.base_estimates[enemy_home] = 0.0\n        turn = int(obs["turn"])\n        horizon = min(9, max(1, N_TURNS - turn))\n        probabilities = self._demand_forecast(obs, horizon)\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        heavy = obs["player_heavy"]\n        light = obs["player_light"]\n        units = []\n        # Heavy units establish capacity advantages; lights cheaply fill gaps.\n        for kind, counts in (("heavy", heavy), ("light", light)):\n            for source in range(n):\n                units.extend([(kind, source)] * counts[source])\n        if not units:\n            return []\n\n        old_targets = {}\n        if turn == self.previous_turn + 1 and self.bad_reports < 2:\n            for kind, position, target in self.saved_targets:\n                old_targets.setdefault((kind, position), []).append(target)\n        targets = []\n        for kind, source in units:\n            saved = old_targets.get((kind, source), [])\n            targets.append(saved.pop(0) if saved else source)\n\n        enemy_stay, enemy_move = self._predict_enemy(obs, probabilities, deadline)\n        blend = min(0.8, 0.2 + self.mobility * 0.65)\n        # Precompute all paths from each occupied source. Intermediate positions\n        # earn revenue and pay upkeep, including the first move\'s destination.\n        routes = {}\n        for source in sorted({s for _, s in units}):\n            for target in range(n):\n                position = source\n                path = []\n                for _ in range(horizon):\n                    if position != target:\n                        position = self.hops[position][target]\n                    path.append(position)\n                routes[source, target] = path\n\n        occupancy = [[0] * n for _ in range(horizon)]\n        for (kind, source), target in zip(units, targets):\n            cap = 8 if kind == "heavy" else 3\n            for k, v in enumerate(routes[source, target]):\n                occupancy[k][v] += cap\n\n        # A lookup table makes discontinuous capacity-priority payouts cheap.\n        # It evaluates gain PLUS denial, not proportional sharing.\n        tables = []\n        max_capacity = 140\n        for k in range(horizon):\n            node_tables = []\n            for v in range(n):\n                b = self.base_estimates[v]\n                p = probabilities[k][v]\n                e0, e1 = enemy_stay[v], enemy_move[v]\n                values = []\n                for cap in range(max_capacity + 1):\n                    a, z = payout(cap, e0, b)\n                    c, w = payout(cap, e0, 3 * b)\n                    stationary = (1 - p) * (a - z) + p * (c - w)\n                    a, z = payout(cap, e1, b)\n                    c, w = payout(cap, e1, 3 * b)\n                    moving = (1 - p) * (a - z) + p * (c - w)\n                    values.append((1 - blend) * stationary + blend * moving)\n                node_tables.append(values)\n            tables.append(node_tables)\n            if time.perf_counter() >= deadline:\n                # The existing sticky plan is already fully legal.\n                action = legal_action(units, targets, self.hops, self.adj, heavy, light)\n                self._remember(units, targets, turn)\n                return action\n\n        weights = [0.94 ** k for k in range(horizon)]\n        for sweep in range(4):\n            changed = False\n            order = range(len(units)) if sweep % 2 == 0 else range(len(units) - 1, -1, -1)\n            for i in order:\n                if time.perf_counter() >= deadline:\n                    break\n                kind, source = units[i]\n                cap, cost = (8, 3.0) if kind == "heavy" else (3, 1.0)\n                old = targets[i]\n                for k, v in enumerate(routes[source, old]):\n                    occupancy[k][v] -= cap\n\n                def route_value(target):\n                    value = 0.0\n                    for k, v in enumerate(routes[source, target]):\n                        count = occupancy[k][v]\n                        table = tables[k][v]\n                        gain = table[count + cap] - table[count]\n                        value += weights[k] * (gain - (cost if v != home else 0.0))\n                    # Small hysteresis, not enough to prevent profitable recalls.\n                    if target != old:\n                        value -= 0.10\n                    if target != source:\n                        value -= 0.04\n                    return value\n\n                best, best_value = old, route_value(old)\n                for target in range(n):\n                    value = route_value(target)\n                    if value > best_value + 1e-8:\n                        best, best_value = target, value\n                targets[i] = best\n                changed |= best != old\n                for k, v in enumerate(routes[source, best]):\n                    occupancy[k][v] += cap\n            if not changed or time.perf_counter() >= deadline:\n                break\n\n        action = legal_action(units, targets, self.hops, self.adj, heavy, light)\n        self._remember(units, targets, turn)\n        return action\n\n    def _remember(self, units, targets, turn):\n        self.saved_targets = [\n            (kind, self.hops[source][target] if source != target else source, target)\n            for (kind, source), target in zip(units, targets)\n        ]\n        self.previous_turn = turn\n'
