_FALLBACK_SRC = '# Action format: [(from_node, to_node, unit_type, count), ...]\n# Payout: "if capacity_0 == capacity_1", each serves min(capacity_0, d / 2).\n# Otherwise the larger capacity serves min(capacity_big, d), and the smaller\n# serves min(capacity_small, d - served_big).\n# Cost: "Every deployed unit costs its upkeep every turn"; heavy upkeep is\n# 3.0 and light upkeep is 1.0. Own-base units cost nothing. Moves precede payout.\n\nfrom collections import deque\nimport time\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 70\nCAPACITY = {"heavy": 8, "light": 3}\nUPKEEP = {"heavy": 3.0, "light": 1.0}\n\n\ndef served(own_capacity, opponent_capacity, demand):\n    """Exact own revenue under the specification\'s priority rule."""\n    if own_capacity == opponent_capacity:\n        return min(own_capacity, demand / 2.0)\n    if own_capacity > opponent_capacity:\n        return min(own_capacity, demand)\n    return min(own_capacity, demand - min(opponent_capacity, demand))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] == -1:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n\n    hops = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                for neighbor in adjacency[source]:\n                    if distances[neighbor][target] == distances[source][target] - 1:\n                        hops[source][target] = neighbor\n                        break\n    return adjacency, distances, hops\n\n\ndef legal_action(plan, positions, adjacency):\n    """Validate against original availability, never against incoming units."""\n    available = {kind: list(positions[kind]) for kind in ("heavy", "light")}\n    combined = {}\n    n = len(adjacency)\n    for source, destination, kind, count in plan:\n        if kind not in available:\n            continue\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = min(int(count), int(available[kind][source]))\n        if count <= 0:\n            continue\n        available[kind][source] -= count\n        key = (source, destination, kind)\n        combined[key] = combined.get(key, 0) + count\n\n    return [\n        (int(source), int(destination), kind, int(count))\n        for (source, destination, kind), count in sorted(combined.items())\n    ]\n\n\ndef conservative_plan(obs, adjacency, distances, hops, deadline):\n    n = len(adjacency)\n    home = int(obs["player_base"])\n    enemy_home = int(obs["opponent_base"])\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    positions = {\n        "heavy": list(obs.get("player_heavy", [0] * n)),\n        "light": list(obs.get("player_light", [0] * n)),\n    }\n    if remaining == 0:\n        return [], positions\n\n    demand = obs.get("demand", [None] * n)\n    surge = obs.get("surge_turns_left", [None] * n)\n    enemy_heavy = obs.get("opponent_heavy", [0] * n)\n    enemy_light = obs.get("opponent_light", [0] * n)\n    enemy_capacity = [\n        8 * enemy_heavy[v] + 3 * enemy_light[v] for v in range(n)\n    ]\n\n    # Base demand, unlike a surge, is a dependable recurring income.\n    # Do not guess hidden demand, retain sightings, or enter capacity fights.\n    base = [0.0] * n\n    for node in range(n):\n        if node in (home, enemy_home):\n            continue\n        if demand[node] is not None and surge[node] is not None:\n            base[node] = float(demand[node]) / (3.0 if surge[node] > 0 else 1.0)\n\n    assigned_capacity = [0] * n\n    plan = []\n\n    # First reserve useful positions already occupied, then allocate spare units.\n    # Lights are preferred because their capacity has lower upkeep.\n    units = []\n    for kind in ("light", "heavy"):\n        for source in range(n):\n            if source != home:\n                units.extend((source, kind) for _ in range(positions[kind][source]))\n    for kind in ("light", "heavy"):\n        units.extend((home, kind) for _ in range(positions[kind][home]))\n\n    # A short, conservative payback horizon discourages long expensive trips.\n    horizon = min(8, remaining)\n    for source, kind in units:\n        if time.perf_counter() >= deadline:\n            break\n        capacity = CAPACITY[kind]\n        cost = UPKEEP[kind]\n\n        # Default: return excess units to the only cost-free node.\n        target = home\n        best_score = -cost * max(0, distances[source][home] - 1)\n\n        for node in range(n):\n            if base[node] <= 0.0 or enemy_capacity[node] > 0:\n                continue\n            distance = distances[source][node]\n            if distance < 0 or distance > 3:\n                continue\n            delay = max(0, distance - 1)\n            earning_turns = horizon - delay\n            if earning_turns <= 0:\n                continue\n\n            before = assigned_capacity[node]\n            marginal = (\n                served(before + capacity, enemy_capacity[node], base[node])\n                - served(before, enemy_capacity[node], base[node])\n            )\n            net = marginal - cost\n            if net <= 0.2:\n                continue\n\n            # Pay upkeep on travel turns too; reserve enough profit for a\n            # possible return trip. Never deploy solely for transient surges.\n            return_distance = distances[node][home]\n            trip_reserve = cost * max(0, return_distance - 1)\n            score = earning_turns * marginal - horizon * cost - trip_reserve\n            if source != node:\n                score -= 0.35 * distance\n            else:\n                score += 0.15  # stable allocations beat marginal reshuffles\n\n            # Require a strictly positive, clearly amortized deployment.\n            if score > max(0.25, best_score) + 1e-9:\n                best_score = score\n                target = node\n\n        if target != home:\n            assigned_capacity[target] += capacity\n        if target != source:\n            destination = hops[source][target]\n            if destination >= 0:\n                plan.append((source, destination, kind, 1))\n\n    return plan, positions\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self._map_key = None\n        self._map_data = None\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if key != self._map_key:\n            self._map_data = preprocess_map(n, edges)\n            self._map_key = key\n\n        adjacency, distances, hops = self._map_data\n        plan, positions = conservative_plan(\n            obs, adjacency, distances, hops, deadline\n        )\n        return legal_action(plan, positions, adjacency)\n'
